CREATE TABLE posts (
  id uuid PRIMARY KEY,
  body text NOT NULL
);

CREATE TABLE likes (
  id uuid PRIMARY KEY,
  post_id uuid NOT NULL
);

CREATE TABLE follows (
  id uuid PRIMARY KEY,
  follower_id uuid NOT NULL
);

CREATE TABLE reposts (
  id uuid PRIMARY KEY,
  post_id uuid NOT NULL
);

CREATE TABLE profiles (
  id uuid PRIMARY KEY,
  handle text NOT NULL
);

CREATE TABLE notifications (
  id uuid PRIMARY KEY,
  kind text NOT NULL
);
